        "status": "final",
        "code": {
          "text": "Testicular, hernia, and inguinal lymph node examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Testes normal; no hernia or inguinal lymphadenopathy."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Acute balanitis"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No acute balanitis."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Betamethasone 0.05% cream"
        },
        "subject": {
          "reference": "Patient/patient-1"
