            "text": "Apply a small amount to the tight ring twice daily for 6 weeks, with gentle retraction only to mild tension. Stop if cracking or bleeding occurs.",
            "route": {
              "text": "Topical"
            },
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d",
                "boundsDuration": {
                  "value": 6,
                  "unit": "weeks",
                  "system": "http://unitsofmeasure.org",
                  "code": "wk"
                }
              }
            }
          }
        ]
